import { vec3 } from 'gl-matrix';
import { Events } from '@cornerstonejs/tools/enums';
import { getEnabledElement } from '@cornerstonejs/core';
import type { Types } from '@cornerstonejs/core';
import { AnnotationTool, cursors, drawing, state } from '@cornerstonejs/tools';
import { getAnnotations } from '@cornerstonejs/tools/annotation/annotationState';
import { isAnnotationVisible } from '@cornerstonejs/tools/annotation/annotationVisibility';
import type {
  Annotation,
  Annotations,
  EventTypes,
  PublicToolProps,
  SVGDrawingHelper,
  ToolHandle,
  ToolProps,
} from '@cornerstonejs/tools/types';
import { servicesManager } from '../../../../platform/app/src/App';
import { endImplantDrag, moveImplantHandle } from '../utils/implants/implantEdition';

interface ImplantAnnotation extends Annotation {
  metadata: Annotation['metadata'] & {
    viewportId: string;
    toothNumber: number;
  };
  data: {
    handles: {
      // points = [position, orientation, apex, side], indexed by activehandleIndex
      points: Types.Point3[];
      activeHandleIndex: number | null;
    };
  };
}

const POSITION_COLOR = 'rgb(255, 255, 0)';
const ORIENTATION_COLOR = 'rgb(0, 255, 255)';
const SIZE_COLOR = 'rgb(255, 0, 255)';

const HANDLE_PROXIMITY = 6;
const RESIZE_CURSORS = ['ew-resize', 'nwse-resize', 'ns-resize', 'nesw-resize'];

// Resize cursor along the canvas direction between two points
const getResizeCursor = (from: Types.Point2, to: Types.Point2) => {
  const angle = Math.atan2(to[1] - from[1], to[0] - from[0]);
  const index = Math.round(angle / (Math.PI / 4));
  return RESIZE_CURSORS[((index % 4) + 4) % 4];
};

// Handles of the edited implant on the panoramic and the central dentascan
class ImplantTool extends AnnotationTool {
  static toolName = 'Implant';

  editData: {
    annotation: ImplantAnnotation;
    handleIndex: number;
    hasMoved: boolean;
  } | null = null;

  constructor(
    toolProps: PublicToolProps = {},
    defaultToolProps: ToolProps = {
      supportedInteractionTypes: ['Mouse'],
      configuration: {},
    }
  ) {
    super(toolProps, defaultToolProps);
  }

  // Annotations are only created by panoramicService
  addNewAnnotation = (): ImplantAnnotation => {
    return undefined;
  };

  // The implant can only be grabbed by its handles
  isPointNearTool = (): boolean => {
    return false;
  };

  toolSelectedCallback = (): void => {};

  mouseMoveCallback = (evt: EventTypes.MouseMoveEventType, annotations?: Annotations): boolean => {
    const { element, currentPoints } = evt.detail;
    const { viewport } = getEnabledElement(element);

    let cursor = '';
    for (const annotation of (annotations ?? []) as ImplantAnnotation[]) {
      const handle = this.getHandleNearImagePoint(
        element,
        annotation,
        currentPoints.canvas,
        HANDLE_PROXIMITY
      );
      if (handle) {
        const handleIndex = annotation.data.handles.points.findIndex(point => point === handle);
        cursor = this._getHandleCursor(viewport, annotation, handleIndex);
      }
    }
    viewport.canvas.style.cursor = cursor;

    return false;
  };

  _getHandleCursor = (
    viewport: Types.IViewport,
    annotation: ImplantAnnotation,
    handleIndex: number
  ): string => {
    if (handleIndex === 0) {
      return 'move';
    }
    if (handleIndex === 1) {
      return cursors.SVGMouseCursor.getDefinedCursor(
        'Rotate',
        false,
        'rgb(255, 255, 255)'
      ).getStyleProperty();
    }

    const [position, , apex, side] = annotation.data.handles.points.map(point =>
      viewport.worldToCanvas(point)
    );
    if (handleIndex === 2) {
      return getResizeCursor(position, apex);
    }
    const center: Types.Point2 = [(position[0] + apex[0]) / 2, (position[1] + apex[1]) / 2];
    return getResizeCursor(center, side);
  };

  handleSelectedCallback(
    evt: EventTypes.InteractionEventType,
    annotation: ImplantAnnotation,
    handle: ToolHandle
  ): void {
    const { element } = evt.detail;

    const handleIndex = annotation.data.handles.points.findIndex(point => point === handle);
    this.editData = { annotation, handleIndex, hasMoved: false };
    this._activateModify(element);

    evt.preventDefault();
  }

  _dragCallback = (evt: EventTypes.InteractionEventType): void => {
    const { annotation, handleIndex } = this.editData;
    this.editData.hasMoved = true;

    moveImplantHandle(servicesManager, annotation, handleIndex, evt.detail.currentPoints.world);
  };

  _endCallback = (evt: EventTypes.InteractionEventType): void => {
    this._endEdition(evt.detail.element);
  };

  cancel = (element: HTMLDivElement) => {
    this._endEdition(element);
  };

  _endEdition = (element: HTMLDivElement) => {
    if (!this.editData) {
      return;
    }

    this._deactivateModify(element);
    const { annotation, hasMoved } = this.editData;
    annotation.data.handles.activeHandleIndex = null;
    this.editData = null;

    if (hasMoved) {
      endImplantDrag(servicesManager);
    }
  };

  _activateModify = (element: HTMLDivElement) => {
    state.isInteractingWithTool = true;

    element.addEventListener(Events.MOUSE_UP, this._endCallback);
    element.addEventListener(Events.MOUSE_DRAG, this._dragCallback);
    element.addEventListener(Events.MOUSE_CLICK, this._endCallback);
  };

  _deactivateModify = (element: HTMLDivElement) => {
    state.isInteractingWithTool = false;

    element.removeEventListener(Events.MOUSE_UP, this._endCallback);
    element.removeEventListener(Events.MOUSE_DRAG, this._dragCallback);
    element.removeEventListener(Events.MOUSE_CLICK, this._endCallback);
  };

  // Implants shown and editable in the element's viewport,
  // only the displayed slice's ones on a dentascan
  filterInteractableAnnotationsForElement(
    element: HTMLDivElement,
    annotations: Annotations
  ): Annotations | undefined {
    const { viewport } = getEnabledElement(element);
    const viewportAnnotations = annotations.filter(
      (annotation: ImplantAnnotation) => annotation.metadata.viewportId === viewport.id
    );
    if (!viewportAnnotations.length || viewport.id === 'panoramic') {
      return viewportAnnotations;
    }

    const { focalPoint, viewPlaneNormal } = viewport.getCamera();
    const { imageData } = viewport.getImageData();
    const halfSliceThickness = imageData.getSpacing()[2] / 2;

    return viewportAnnotations.filter((annotation: ImplantAnnotation) => {
      const [position] = annotation.data.handles.points;
      const offset = vec3.subtract(vec3.create(), position, focalPoint);
      return Math.abs(vec3.dot(offset, viewPlaneNormal)) < halfSliceThickness;
    });
  }

  renderAnnotation = (
    enabledElement: Types.IEnabledElement,
    svgDrawingHelper: SVGDrawingHelper
  ): boolean => {
    const { viewport } = enabledElement;
    const { element } = viewport;

    let annotations = getAnnotations(this.getToolName(), element);
    if (!annotations?.length) {
      return false;
    }
    annotations = this.filterInteractableAnnotationsForElement(element, annotations);

    let renderStatus = false;
    for (const annotation of annotations as ImplantAnnotation[]) {
      const { annotationUID, data } = annotation;
      if (!isAnnotationVisible(annotationUID)) {
        continue;
      }

      const [position, orientation, apex, side] = data.handles.points.map(point =>
        viewport.worldToCanvas(point)
      );

      // Outline of the implant, it follows its resize handles during the drag
      const offset = [side[0] - (position[0] + apex[0]) / 2, side[1] - (position[1] + apex[1]) / 2];
      const corner = (point: Types.Point2, sign: number): Types.Point2 => [
        point[0] + sign * offset[0],
        point[1] + sign * offset[1],
      ];
      drawing.drawPolyline(
        svgDrawingHelper,
        annotationUID,
        'outline',
        [corner(position, 1), corner(apex, 1), corner(apex, -1), corner(position, -1)],
        { color: SIZE_COLOR, width: 1, closePath: true }
      );
      drawing.drawHandles(svgDrawingHelper, annotationUID, 'size', [apex, side], {
        color: SIZE_COLOR,
      });

      drawing.drawLine(svgDrawingHelper, annotationUID, 'axis', position, orientation, {
        color: ORIENTATION_COLOR,
        width: 1,
        lineDash: '4,4',
      });
      drawing.drawHandles(svgDrawingHelper, annotationUID, 'position', [position], {
        color: POSITION_COLOR,
      });
      drawing.drawHandles(svgDrawingHelper, annotationUID, 'orientation', [orientation], {
        color: ORIENTATION_COLOR,
      });
      renderStatus = true;
    }

    return renderStatus;
  };
}

export default ImplantTool;
export type { ImplantAnnotation };
