import {
  cache,
  Enums as csEnums,
  geometryLoader,
  getEnabledElementByViewportId,
} from '@cornerstonejs/core';
import {
  Enums as csToolsEnums,
  segmentation as cstSegmentation,
  utilities as cstUtils,
} from '@cornerstonejs/tools';
import vtkCellArray from '@kitware/vtk.js/Common/Core/CellArray';
import vtkPolyData from '@kitware/vtk.js/Common/DataModel/PolyData';
import * as polySeg from '@cornerstonejs/polymorphic-segmentation';
import { computeSurfaceFromLabelmapSegmentation } from '../../../../node_modules/@cornerstonejs/polymorphic-segmentation/dist/esm/Surface/surfaceComputationStrategies.js';

type RawSurface = {
  segmentIndex: number;
  data: { points: Float32Array | number[]; polys: Float32Array | number[] };
};

const SURFACE = csToolsEnums.SegmentationRepresentations.Surface;

// Module namespace exports are getter-only, so the registered addon is a plain
// object. Cornerstone looks up updateSurfaceData on it when the labelmap
// changes; that lookup stays a no-op. The other conversions are unchanged.
export const polySegAddon: typeof polySeg = {
  canComputeRequestedRepresentation: polySeg.canComputeRequestedRepresentation,
  computeContourData: polySeg.computeContourData,
  computeLabelmapData: polySeg.computeLabelmapData,
  computeSurfaceData,
  updateSurfaceData: () => Promise.resolve(),
  init: polySeg.init,
  clipAndCacheSurfacesForViewport: polySeg.clipAndCacheSurfacesForViewport,
  extractContourData: polySeg.extractContourData,
  createAndAddContourSegmentationsFromClippedSurfaces:
    polySeg.createAndAddContourSegmentationsFromClippedSurfaces,
};

const surfaceGeometryId = (segmentationId: string, segmentIndex: number) =>
  `segmentation_${segmentationId}_surface_${segmentIndex}`;

const surfaceRepresentationUID = (segmentationId: string, segmentIndex: number) =>
  `${segmentationId}-${SURFACE}-${segmentIndex}`;

const FALLBACK_SEGMENT_COLOR = [200, 200, 200];

/**
 * The 3D viewport often asks for a color before its own representation exists,
 * or after that representation was removed while the worker was still running.
 * getSegmentIndexColor then returns null and the library crashes on .slice.
 */
function segmentColor(segmentationId: string, segmentIndex: number): number[] {
  const groups = cstSegmentation.state.getSegmentationRepresentationsBySegmentationId(
    segmentationId
  ) as { viewportId: string; representations: { colorLUTIndex?: number }[] }[];

  for (const group of groups) {
    try {
      const color = cstSegmentation.config.color.getSegmentIndexColor(
        group.viewportId,
        segmentationId,
        segmentIndex
      );
      if (color) {
        return color.slice(0, 3);
      }
    } catch {
      // This viewport's LUT is missing. Try the next one.
    }
  }

  for (const group of groups) {
    const lut = cstSegmentation.state.getColorLUT(group.representations[0]?.colorLUTIndex);
    const color = lut?.[segmentIndex];
    if (color) {
      return color.slice(0, 3);
    }
  }

  return FALLBACK_SEGMENT_COLOR;
}

async function computeSurfaceData(
  segmentationId: string,
  options: { segmentIndices?: number[] } = {}
) {
  const segmentation = cstSegmentation.state.getSegmentation(segmentationId);
  if (segmentation?.representationData?.Contour && !segmentation.representationData.Labelmap) {
    return polySeg.computeSurfaceData(segmentationId, options);
  }

  const rawSurfaces = (await computeSurfaceFromLabelmapSegmentation(segmentationId, {
    segmentIndices: options.segmentIndices,
  })) as RawSurface[] | undefined;
  const geometryIds = new Map<number, string>();
  if (!rawSurfaces?.length) {
    return { geometryIds };
  }

  await Promise.all(
    rawSurfaces.map(async ({ segmentIndex, data }) => {
      const geometryId = surfaceGeometryId(segmentationId, segmentIndex);
      const color = segmentColor(segmentationId, segmentIndex);
      const existing = cache.getGeometry(geometryId);
      if (!data?.points) {
        // The worker returns no points for an empty segment (labelmap not filled yet).
        // A geometry cached by a previous load is emptied but not listed, so no empty
        // actor is created: the actor and its camera reset come with the real data.
        if (existing?.data) {
          existing.data.points = [];
          existing.data.polys = [];
        }
        return;
      }
      geometryIds.set(segmentIndex, geometryId);
      if (existing?.data) {
        existing.data.points = data.points;
        existing.data.polys = data.polys;
        existing.data.color = color;
        return;
      }

      try {
        await geometryLoader.createAndCacheGeometry(geometryId, {
          type: csEnums.GeometryType.SURFACE,
          geometryData: {
            id: geometryId,
            color,
            frameOfReferenceUID: 'test-frameOfReferenceUID',
            points: data.points,
            polys: data.polys,
            segmentIndex,
          },
        });
      } catch (error) {
        geometryIds.delete(segmentIndex);
        console.warn(
          `Surface cache failed for segmentation ${segmentationId} segment ${segmentIndex}`,
          error
        );
      }
    })
  );

  return { geometryIds };
}

const replaceSurfaceActorData = (
  segmentationId: string,
  segmentIndex: number,
  points: RawSurface['data']['points'],
  polys: RawSurface['data']['polys']
) => {
  const representationUID = surfaceRepresentationUID(segmentationId, segmentIndex);
  cstSegmentation.state.getViewportIdsWithSegmentation(segmentationId).forEach(viewportId => {
    const viewport = getEnabledElementByViewportId(viewportId)?.viewport;
    if (!viewport || viewport.type !== csEnums.ViewportType.VOLUME_3D) {
      return;
    }

    const actorEntry = viewport
      .getActors()
      .find(actor => actor.representationUID === representationUID);
    if (!actorEntry) {
      return;
    }

    const polyData = vtkPolyData.newInstance();
    polyData.getPoints().setData(points, 3);
    polyData.setPolys(
      vtkCellArray.newInstance({
        values: Float32Array.from(polys as ArrayLike<number>),
      })
    );
    const mapper = actorEntry.actor.getMapper();
    mapper.setInputData(polyData);
    mapper.modified();
    viewport.render();
  });
};

const cacheMissingSurface = async (
  segmentationId: string,
  segmentIndex: number,
  data: RawSurface['data'],
  geometryIds: Map<number, string>
) => {
  const geometryId = surfaceGeometryId(segmentationId, segmentIndex);
  const color = segmentColor(segmentationId, segmentIndex);
  await geometryLoader.createAndCacheGeometry(geometryId, {
    type: csEnums.GeometryType.SURFACE,
    geometryData: {
      id: geometryId,
      color,
      frameOfReferenceUID: 'test-frameOfReferenceUID',
      points: data.points,
      polys: data.polys,
      segmentIndex,
    },
  });
  geometryIds.set(segmentIndex, geometryId);
  replaceSurfaceActorData(segmentationId, segmentIndex, data.points, data.polys);
};

/**
 * Recomputes surfaces from the axial labelmap.
 * The library updater reads a Surface representation on every viewport that
 * holds the segmentation and crashes on the 2D slices, which only have a labelmap.
 */
export async function updateSurfaceFromLabelmap(segmentationId: string): Promise<void> {
  const surfaces = (await computeSurfaceFromLabelmapSegmentation(segmentationId)) as
    | RawSurface[]
    | undefined;
  if (!surfaces) {
    return;
  }

  const segmentation = cstSegmentation.state.getSegmentation(segmentationId);
  const geometryIds = segmentation?.representationData?.[SURFACE]?.geometryIds as
    | Map<number, string>
    | undefined;
  if (!geometryIds) {
    return;
  }

  const indices = cstUtils.segmentation.getUniqueSegmentIndices(segmentationId) as number[];

  geometryIds.forEach((geometryId, segmentIndex) => {
    if (indices.includes(segmentIndex)) {
      return;
    }
    const surface = cache.getGeometry(geometryId)?.data;
    if (surface) {
      surface.points = [];
      surface.polys = [];
    }
    replaceSurfaceActorData(segmentationId, segmentIndex, [], []);
  });

  if (!indices.length) {
    cstSegmentation.triggerSegmentationEvents.triggerSegmentationModified(segmentationId);
    return;
  }

  await Promise.all(
    surfaces.map(async ({ segmentIndex, data }) => {
      const geometryId = surfaceGeometryId(segmentationId, segmentIndex);
      const surface = cache.getGeometry(geometryId)?.data;
      if (!surface) {
        if (!data?.points) {
          return;
        }
        await cacheMissingSurface(segmentationId, segmentIndex, data, geometryIds);
        return;
      }

      if (indices.includes(segmentIndex) && data?.points) {
        surface.points = data.points;
        surface.polys = data.polys;
        geometryIds.set(segmentIndex, geometryId);
        replaceSurfaceActorData(segmentationId, segmentIndex, data.points, data.polys);
        return;
      }

      surface.points = [];
      surface.polys = [];
      replaceSurfaceActorData(segmentationId, segmentIndex, [], []);
    })
  );

  cstSegmentation.triggerSegmentationEvents.triggerSegmentationModified(segmentationId);
}
