import ArrowAnnotate from './ArrowAnnotate';

const LineSegment = {
  toAnnotation: measurement => {},

  toMeasurement: (
    csToolsEventDetail,
    displaySetService,
    cornerstoneViewportService,
    getValueTypeFromToolType,
    customizationService
  ) => {
    const { metadata, data } = csToolsEventDetail.annotation;
    if (!metadata || !data) {
      console.warn('Line segment tool: Missing metadata or data');
      return null;
    }
    return ArrowAnnotate.toMeasurement(
      csToolsEventDetail,
      displaySetService,
      cornerstoneViewportService,
      getValueTypeFromToolType,
      customizationService
    );
  },
};

export default LineSegment;
