import { Enums as csEnums, cache, eventTarget, getEnabledElement } from '@cornerstonejs/core';
import { Enums as csToolsEnums, segmentation as cstSegmentation } from '@cornerstonejs/tools';
import type { Types as csTypes } from '@cornerstonejs/core';

const LABELMAP = csToolsEnums.SegmentationRepresentations.Labelmap;

const SMOOTH_PASSES = 3;
const SMOOTH_WINDOW = 2;
const CHAIKIN_ITERATIONS = 2;
const FILL_ALPHA = 0.45;
const OUTLINE_WIDTH = 1.5;
const AXIS_DOT_THRESHOLD = 0.99;

type Point2 = [number, number];
type SegmentContours = Map<number, Point2[][]>;
type SavedStyle = {
  renderFill?: boolean;
  renderOutline?: boolean;
  renderFillInactive?: boolean;
  renderOutlineInactive?: boolean;
};

let enabled = false;
let servicesManagerRef: AppTypes.ServicesManager | null = null;

const contourCache = new Map<string, SegmentContours>();
const savedStyles = new Map<string, SavedStyle>();
const overlays = new Map<string, HTMLCanvasElement>();
const attachedElements = new Map<string, HTMLElement>();
const unsubscribeFns: Array<() => void> = [];

const styleKey = (viewportId: string, segmentationId: string) =>
  `${viewportId}::${segmentationId}`;

const cacheKey = (segmentationId: string, axis: number, slice: number) =>
  `${segmentationId}|${axis}|${slice}`;

// 'implants' (axial), 'dentascan_implants', 'panoramic_implant'
const isImplantSegmentation = (segmentationId: string) =>
  /(^|_)implants?$/.test(segmentationId);

const isExcludedViewportId =(viewportId: string) =>
  viewportId === 'volume3d' ||
  viewportId.startsWith('volume3d') ||
  viewportId.includes('3d');

/**
 * Smooth overlay targets every orthographic volume slice viewport
 * (axial / coronal / sagittal / dentascan / mpr-*) and the stack ones (panoramic), not the 3D.
 */
function isTargetViewportId(viewportId: string): boolean {
  if (isExcludedViewportId(viewportId)) {
    return false;
  }

  const { cornerstoneViewportService } = servicesManagerRef?.services ?? {};
  if (!cornerstoneViewportService) {
    return (
      viewportId === 'panoramic' ||
      viewportId === 'axial' ||
      viewportId === 'coronal' ||
      viewportId === 'sagittal' ||
      viewportId.startsWith('dentascan') ||
      viewportId.startsWith('mpr-')
    );
  }

  try {
    const viewportInfo = cornerstoneViewportService.getViewportInfo(viewportId);
    const viewportType = viewportInfo?.getViewportType?.();
    if (viewportType === csEnums.ViewportType.VOLUME_3D) {
      return false;
    }
    if (
      viewportType === csEnums.ViewportType.ORTHOGRAPHIC ||
      viewportType === csEnums.ViewportType.STACK
    ) {
      return true;
    }
    // Fallback by id when type is not yet available
    return (
      viewportId === 'panoramic' ||
      viewportId === 'axial' ||
      viewportId === 'coronal' ||
      viewportId === 'sagittal' ||
      viewportId.startsWith('dentascan') ||
      viewportId.startsWith('mpr-')
    );
  } catch {
    return false;
  }
}

export function isSmoothSegmentationDisplayEnabled(): boolean {
  return enabled;
}

export function setSmoothSegmentationDisplay(
  servicesManager: AppTypes.ServicesManager,
  nextEnabled: boolean
): void {
  servicesManagerRef = servicesManager;

  if (nextEnabled === enabled) {
    if (nextEnabled) {
      attachAllOverlays();
      hideAllLabelmapStyles();
      requestRenders();
    }
    return;
  }

  enabled = nextEnabled;

  if (enabled) {
    attachGlobalListeners();
    attachAllOverlays();
    hideAllLabelmapStyles();
    requestRenders();
  } else {
    detachGlobalListeners();
    restoreAllLabelmapStyles();
    detachAllOverlays();
    contourCache.clear();
    requestRenders();
  }
}

function getTargetViewportIds(): string[] {
  const { cornerstoneViewportService } = servicesManagerRef?.services ?? {};
  if (!cornerstoneViewportService) {
    return [];
  }
  return cornerstoneViewportService.getViewportIds().filter(isTargetViewportId);
}

function requestRenders(): void {
  const { cornerstoneViewportService } = servicesManagerRef?.services ?? {};
  if (!cornerstoneViewportService) {
    return;
  }
  for (const viewportId of getTargetViewportIds()) {
    const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);
    viewport?.render?.();
  }
}

function attachGlobalListeners(): void {
  detachGlobalListeners();

  eventTarget.addEventListener(
    csToolsEnums.Events.SEGMENTATION_DATA_MODIFIED,
    onSegmentationDataModified as EventListener
  );
  eventTarget.addEventListener(
    csToolsEnums.Events.SEGMENTATION_REPRESENTATION_ADDED,
    onRepresentationChanged as EventListener
  );
  eventTarget.addEventListener(
    csToolsEnums.Events.SEGMENTATION_REPRESENTATION_MODIFIED,
    onRepresentationChanged as EventListener
  );

  const { hangingProtocolService, cornerstoneViewportService } =
    servicesManagerRef?.services ?? {};

  if (hangingProtocolService) {
    const { unsubscribe } = hangingProtocolService.subscribe(
      hangingProtocolService.EVENTS.PROTOCOL_CHANGED,
      () => {
        if (!enabled) {
          return;
        }
        setTimeout(() => {
          // Viewport recreation may reset styles; force re-hide.
          savedStyles.clear();
          attachAllOverlays();
          hideAllLabelmapStyles();
          requestRenders();
        }, 0);
      }
    );
    unsubscribeFns.push(unsubscribe);
  }

  if (cornerstoneViewportService) {
    const { unsubscribe } = cornerstoneViewportService.subscribe(
      cornerstoneViewportService.EVENTS.VIEWPORT_DATA_CHANGED,
      ({ viewportId }) => {
        if (!enabled || !isTargetViewportId(viewportId)) {
          return;
        }
        setTimeout(() => {
          clearSavedStylesForViewport(viewportId);
          attachOverlay(viewportId);
          hideLabelmapStylesForViewport(viewportId);
          const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId);
          viewport?.render?.();
        }, 0);
      }
    );
    unsubscribeFns.push(unsubscribe);
  }
}

function clearSavedStylesForViewport(viewportId: string): void {
  for (const key of [...savedStyles.keys()]) {
    if (key.startsWith(`${viewportId}::`)) {
      savedStyles.delete(key);
    }
  }
}

function detachGlobalListeners(): void {
  eventTarget.removeEventListener(
    csToolsEnums.Events.SEGMENTATION_DATA_MODIFIED,
    onSegmentationDataModified as EventListener
  );
  eventTarget.removeEventListener(
    csToolsEnums.Events.SEGMENTATION_REPRESENTATION_ADDED,
    onRepresentationChanged as EventListener
  );
  eventTarget.removeEventListener(
    csToolsEnums.Events.SEGMENTATION_REPRESENTATION_MODIFIED,
    onRepresentationChanged as EventListener
  );

  while (unsubscribeFns.length) {
    const unsub = unsubscribeFns.pop();
    unsub?.();
  }
}

function onSegmentationDataModified(evt: CustomEvent): void {
  if (!enabled) {
    return;
  }
  const segmentationId = evt.detail?.segmentationId as string | undefined;
  if (!segmentationId) {
    return;
  }
  invalidateCacheForSegmentation(segmentationId);
  requestRenders();
}

function onRepresentationChanged(): void {
  if (!enabled) {
    return;
  }
  hideAllLabelmapStyles();
  requestRenders();
}

function invalidateCacheForSegmentation(segmentationId: string): void {
  const prefix = `${segmentationId}|`;
  for (const key of [...contourCache.keys()]) {
    if (key.startsWith(prefix)) {
      contourCache.delete(key);
    }
  }
}

function hideAllLabelmapStyles(): void {
  for (const viewportId of getTargetViewportIds()) {
    hideLabelmapStylesForViewport(viewportId);
  }
}

function hideLabelmapStylesForViewport(viewportId: string): void {
  const { segmentationService } = servicesManagerRef?.services ?? {};
  if (!segmentationService) {
    return;
  }

  const representations = segmentationService.getSegmentationRepresentations(viewportId, {
    type: LABELMAP,
  });

  for (const representation of representations) {
    const { segmentationId } = representation;
    const key = styleKey(viewportId, segmentationId);
    if (savedStyles.has(key)) {
      continue;
    }

    const current = segmentationService.getStyle({
      viewportId,
      segmentationId,
      type: LABELMAP,
    }) as SavedStyle;
    savedStyles.set(key, {
      renderFill: current?.renderFill,
      renderOutline: current?.renderOutline,
      renderFillInactive: current?.renderFillInactive,
      renderOutlineInactive: current?.renderOutlineInactive,
    });

    segmentationService.setStyle(
      { type: LABELMAP, viewportId, segmentationId },
      {
        renderFill: false,
        renderOutline: false,
        renderFillInactive: false,
        renderOutlineInactive: false,
      }
    );
  }
}

function restoreAllLabelmapStyles(): void {
  const { segmentationService } = servicesManagerRef?.services ?? {};
  if (!segmentationService) {
    savedStyles.clear();
    return;
  }

  for (const [key, style] of savedStyles.entries()) {
    const [viewportId, segmentationId] = key.split('::');
    try {
      segmentationService.setStyle({ type: LABELMAP, viewportId, segmentationId }, style);
    } catch {
      // Viewport or segmentation may have been removed.
    }
  }
  savedStyles.clear();
}

function attachAllOverlays(): void {
  for (const viewportId of getTargetViewportIds()) {
    attachOverlay(viewportId);
  }
}

function attachOverlay(viewportId: string): void {
  const { cornerstoneViewportService } = servicesManagerRef?.services ?? {};
  if (!cornerstoneViewportService) {
    return;
  }

  const viewport = cornerstoneViewportService.getCornerstoneViewport(viewportId) as
    | csTypes.IViewport
    | null;
  if (!viewport?.element) {
    return;
  }

  const element = viewport.element as HTMLElement;

  // Put the overlay inside cornerstone's viewport div, right before the SVG annotation layer,
  // so the editing tools (drawn in the SVG) stay in front of the smoothed segmentation.
  const host =
    (element.querySelector(':scope > .viewport-element') as HTMLElement | null) ?? element;
  if (getComputedStyle(host).position === 'static') {
    host.style.position = 'relative';
  }
  const svgLayer = host.querySelector(':scope > .svg-layer');

  let canvas = overlays.get(viewportId);
  if (!canvas) {
    canvas = document.createElement('canvas');
    canvas.dataset.smoothSegOverlay = viewportId;
    canvas.style.position = 'absolute';
    canvas.style.inset = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.pointerEvents = 'none';
    overlays.set(viewportId, canvas);
  }
  const isWellPlaced =
    canvas.parentElement === host && (!svgLayer || canvas.nextSibling === svgLayer);
  if (!isWellPlaced) {
    host.insertBefore(canvas, svgLayer ?? null);
  }

  const previouslyAttached = attachedElements.get(viewportId);
  if (previouslyAttached && previouslyAttached !== element) {
    previouslyAttached.removeEventListener(
      csEnums.Events.IMAGE_RENDERED,
      onImageRendered as EventListener
    );
  }
  if (previouslyAttached !== element) {
    element.addEventListener(csEnums.Events.IMAGE_RENDERED, onImageRendered as EventListener);
    attachedElements.set(viewportId, element);
  }
}

function detachAllOverlays(): void {
  for (const [viewportId, element] of attachedElements.entries()) {
    element.removeEventListener(csEnums.Events.IMAGE_RENDERED, onImageRendered as EventListener);
    attachedElements.delete(viewportId);
  }

  for (const canvas of overlays.values()) {
    canvas.remove();
  }
  overlays.clear();
}

function onImageRendered(evt: CustomEvent): void {
  if (!enabled) {
    return;
  }

  const element = evt.currentTarget as HTMLElement;
  const enabledElement = getEnabledElement(element);
  if (!enabledElement?.viewport) {
    return;
  }

  const { viewport } = enabledElement;
  const viewportId = viewport.id;
  if (!isTargetViewportId(viewportId)) {
    return;
  }

  const canvas = overlays.get(viewportId);
  if (!canvas) {
    return;
  }

  drawViewportOverlay(viewportId, viewport as csTypes.IViewport, canvas);
}

function drawViewportOverlay(
  viewportId: string,
  viewport: csTypes.IViewport,
  canvas: HTMLCanvasElement
): void {
  const { segmentationService } = servicesManagerRef?.services ?? {};
  if (!segmentationService) {
    return;
  }

  const dpr = window.devicePixelRatio || 1;
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  if (width <= 0 || height <= 0) {
    return;
  }

  if (canvas.width !== Math.round(width * dpr) || canvas.height !== Math.round(height * dpr)) {
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
  }

  const ctx = canvas.getContext('2d');
  if (!ctx) {
    return;
  }

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const representations = segmentationService.getSegmentationRepresentations(viewportId, {
    type: LABELMAP,
  });
  if (!representations?.length) {
    return;
  }

  const renderInactive = segmentationService.getRenderInactiveSegmentations(viewportId);
  const activeSegmentation = segmentationService.getActiveSegmentation(viewportId);
  const activeSegmentationId = activeSegmentation?.segmentationId;

  const camera = viewport.getCamera?.();
  const viewPlaneNormal = camera?.viewPlaneNormal;
  const focalPoint = camera?.focalPoint;
  if (!viewPlaneNormal || !focalPoint) {
    return;
  }

  // Implants are drawn last so they stay on top of the other segmentations
  const orderedRepresentations = [...representations].sort(
    (a, b) => Number(isImplantSegmentation(a.segmentationId)) -
      Number(isImplantSegmentation(b.segmentationId))
  );

  for (const representation of orderedRepresentations) {
    if (representation.visible === false) {
      continue;
    }
    if (
      !renderInactive &&
      activeSegmentationId &&
      representation.segmentationId !== activeSegmentationId
    ) {
      continue;
    }

    const { segmentationId, segments } = representation;
    const sliceContours =
      getVolumeSliceContours(segmentationId, viewPlaneNormal, focalPoint) ??
      getStackImageContours(viewportId, segmentationId, viewport);
    if (!sliceContours) {
      continue;
    }
    const { contoursBySegment, toWorld } = sliceContours;

    for (const [segmentIndex, loops] of contoursBySegment.entries()) {
      const segmentRep = segments?.[segmentIndex];
      if (segmentRep && segmentRep.visible === false) {
        continue;
      }
      if (!loops?.length) {
        continue;
      }

      const color =
        segmentRep?.color ??
        segmentationService.getSegmentColor(viewportId, segmentationId, segmentIndex);
      if (!color) {
        continue;
      }

      const path = new Path2D();
      for (const loop of loops) {
        if (loop.length < 3) {
          continue;
        }
        let started = false;
        for (const [u, v] of loop) {
          const canvasPoint = viewport.worldToCanvas(toWorld(u, v));
          if (!started) {
            path.moveTo(canvasPoint[0], canvasPoint[1]);
            started = true;
          } else {
            path.lineTo(canvasPoint[0], canvasPoint[1]);
          }
        }
        path.closePath();
      }

      ctx.fillStyle = `rgba(${color[0]}, ${color[1]}, ${color[2]}, ${FILL_ALPHA})`;
      ctx.fill(path, 'evenodd');
      ctx.strokeStyle = `rgba(${color[0]}, ${color[1]}, ${color[2]}, 1)`;
      ctx.lineWidth = OUTLINE_WIDTH;
      ctx.stroke(path);
    }
  }
}

type SliceContours = {
  contoursBySegment: SegmentContours;
  toWorld: (u: number, v: number) => csTypes.Point3;
};

// Volume labelmap (axial / coronal / sagittal / dentascan): contours of the displayed slice
function getVolumeSliceContours(
  segmentationId: string,
  viewPlaneNormal: csTypes.Point3,
  focalPoint: csTypes.Point3
): SliceContours | null {
  const { segmentationService } = servicesManagerRef?.services ?? {};
  const volume = segmentationService?.getLabelmapVolume(segmentationId);
  if (!volume?.imageData || !volume?.voxelManager || !volume?.dimensions) {
    return null;
  }

  const { imageData, voxelManager, dimensions } = volume;
  const axis = getSliceAxis(imageData, viewPlaneNormal);
  if (axis === null) {
    return null;
  }

  const ijk = imageData.worldToIndex(focalPoint);
  const slice = Math.round(ijk[axis]);
  if (slice < 0 || slice >= dimensions[axis]) {
    return null;
  }

  const key = cacheKey(segmentationId, axis, slice);
  let contoursBySegment = contourCache.get(key);
  if (!contoursBySegment) {
    contoursBySegment = computeSliceContours(voxelManager, dimensions, axis, slice);
    contourCache.set(key, contoursBySegment);
  }

  const toWorld = (u: number, v: number) => {
    const ijkPoint: [number, number, number] = [0, 0, 0];
    if (axis === 0) {
      ijkPoint[0] = slice;
      ijkPoint[1] = u;
      ijkPoint[2] = v;
    } else if (axis === 1) {
      ijkPoint[0] = u;
      ijkPoint[1] = slice;
      ijkPoint[2] = v;
    } else {
      ijkPoint[0] = u;
      ijkPoint[1] = v;
      ijkPoint[2] = slice;
    }
    return imageData.indexToWorld(ijkPoint) as csTypes.Point3;
  };

  return { contoursBySegment, toWorld };
}

// Stack labelmap (panoramic): contours of the labelmap image of the displayed image
function getStackImageContours(
  viewportId: string,
  segmentationId: string,
  viewport: csTypes.IViewport
): SliceContours | null {
  let labelmapImageId: string | undefined;
  try {
    labelmapImageId = cstSegmentation.state.getCurrentLabelmapImageIdForViewport(
      viewportId,
      segmentationId
    );
  } catch {
    return null;
  }
  const labelmapImage = labelmapImageId ? cache.getImage(labelmapImageId) : null;
  const viewportImageData = (viewport as csTypes.IStackViewport).getImageData?.()?.imageData;
  if (!labelmapImage || !viewportImageData) {
    return null;
  }

  const { columns: width, rows: height } = labelmapImage;
  const key = `${segmentationId}|stack|${labelmapImageId}`;
  let contoursBySegment = contourCache.get(key);
  if (!contoursBySegment) {
    const pixelData = labelmapImage.getPixelData();
    contoursBySegment = computeContours((u, v) => Number(pixelData[v * width + u] ?? 0), width, height);
    contourCache.set(key, contoursBySegment);
  }

  const toWorld = (u: number, v: number) =>
    viewportImageData.indexToWorld([u, v, 0]) as csTypes.Point3;

  return { contoursBySegment, toWorld };
}

function getSliceAxis(
  imageData: { indexToWorld: (ijk: number[]) => number[] },
  viewPlaneNormal: number[]
): number | null {
  const origin = imageData.indexToWorld([0, 0, 0]);
  let bestAxis = -1;
  let bestDot = -1;

  for (let axis = 0; axis < 3; axis++) {
    const tipIjk = [0, 0, 0];
    tipIjk[axis] = 1;
    const tip = imageData.indexToWorld(tipIjk);
    const dir = [tip[0] - origin[0], tip[1] - origin[1], tip[2] - origin[2]];
    const len = Math.hypot(dir[0], dir[1], dir[2]) || 1;
    const nx = dir[0] / len;
    const ny = dir[1] / len;
    const nz = dir[2] / len;
    const dot = Math.abs(
      nx * viewPlaneNormal[0] + ny * viewPlaneNormal[1] + nz * viewPlaneNormal[2]
    );
    if (dot > bestDot) {
      bestDot = dot;
      bestAxis = axis;
    }
  }

  if (bestDot < AXIS_DOT_THRESHOLD) {
    return null;
  }
  return bestAxis;
}

function computeSliceContours(
  voxelManager: {
    getSliceData?: (args: { sliceIndex: number; slicePlane: number }) => ArrayLike<number>;
    getAtIJK: (i: number, j: number, k: number) => number;
  },
  dimensions: number[],
  axis: number,
  slice: number
): SegmentContours {
  const width = axis === 0 ? dimensions[1] : dimensions[0];
  const height = axis === 0 ? dimensions[2] : axis === 1 ? dimensions[2] : dimensions[1];

  let sliceData: ArrayLike<number> | null = null;
  if (axis === 2 && typeof voxelManager.getSliceData === 'function') {
    try {
      sliceData = voxelManager.getSliceData({ sliceIndex: slice, slicePlane: 2 });
    } catch {
      sliceData = null;
    }
  }

  const getValue = (u: number, v: number): number => {
    if (sliceData) {
      return Number(sliceData[v * width + u] ?? 0);
    }
    if (axis === 0) {
      return Number(voxelManager.getAtIJK(slice, u, v) ?? 0);
    }
    if (axis === 1) {
      return Number(voxelManager.getAtIJK(u, slice, v) ?? 0);
    }
    return Number(voxelManager.getAtIJK(u, v, slice) ?? 0);
  };

  return computeContours(getValue, width, height);
}

function computeContours(
  getValue: (u: number, v: number) => number,
  width: number,
  height: number
): SegmentContours {
  const boundsBySegment = new Map<number, { minU: number; maxU: number; minV: number; maxV: number }>();

  for (let v = 0; v < height; v++) {
    for (let u = 0; u < width; u++) {
      const value = getValue(u, v);
      if (!value) {
        continue;
      }
      const bounds = boundsBySegment.get(value);
      if (!bounds) {
        boundsBySegment.set(value, { minU: u, maxU: u, minV: v, maxV: v });
      } else {
        bounds.minU = Math.min(bounds.minU, u);
        bounds.maxU = Math.max(bounds.maxU, u);
        bounds.minV = Math.min(bounds.minV, v);
        bounds.maxV = Math.max(bounds.maxV, v);
      }
    }
  }

  const result: SegmentContours = new Map();

  for (const [segmentIndex, bounds] of boundsBySegment.entries()) {
    const minU = Math.max(0, bounds.minU - 1);
    const maxU = Math.min(width - 1, bounds.maxU + 1);
    const minV = Math.max(0, bounds.minV - 1);
    const maxV = Math.min(height - 1, bounds.maxV + 1);
    const maskW = maxU - minU + 1;
    const maskH = maxV - minV + 1;
    const mask = new Uint8Array(maskW * maskH);

    for (let v = minV; v <= maxV; v++) {
      for (let u = minU; u <= maxU; u++) {
        if (getValue(u, v) === segmentIndex) {
          mask[(v - minV) * maskW + (u - minU)] = 1;
        }
      }
    }

    const loops = marchingSquares(mask, maskW, maskH, minU, minV)
      .map(loop => smoothClosedLoop(loop))
      .filter(loop => loop.length >= 4);

    if (loops.length) {
      result.set(segmentIndex, loops);
    }
  }

  return result;
}

function marchingSquares(
  mask: Uint8Array,
  width: number,
  height: number,
  offsetU: number,
  offsetV: number
): Point2[][] {
  type EdgePoint = { key: string; x: number; y: number };
  const segments: Array<[EdgePoint, EdgePoint]> = [];

  const hKey = (x: number, y: number) => `h${x},${y}`;
  const vKey = (x: number, y: number) => `v${x},${y}`;

  const at = (x: number, y: number) => {
    if (x < 0 || y < 0 || x >= width || y >= height) {
      return 0;
    }
    return mask[y * width + x];
  };

  for (let y = -1; y < height; y++) {
    for (let x = -1; x < width; x++) {
      const tl = at(x, y) ? 1 : 0;
      const tr = at(x + 1, y) ? 1 : 0;
      const br = at(x + 1, y + 1) ? 1 : 0;
      const bl = at(x, y + 1) ? 1 : 0;
      const code = (tl << 3) | (tr << 2) | (br << 1) | bl;
      if (code === 0 || code === 15) {
        continue;
      }

      const top: EdgePoint = { key: hKey(x, y), x: x + 0.5, y };
      const right: EdgePoint = { key: vKey(x + 1, y), x: x + 1, y: y + 0.5 };
      const bottom: EdgePoint = { key: hKey(x, y + 1), x: x + 0.5, y: y + 1 };
      const left: EdgePoint = { key: vKey(x, y), x, y: y + 0.5 };

      const add = (a: EdgePoint, b: EdgePoint) => segments.push([a, b]);

      switch (code) {
        case 1:
          add(left, bottom);
          break;
        case 2:
          add(bottom, right);
          break;
        case 3:
          add(left, right);
          break;
        case 4:
          add(top, right);
          break;
        case 5:
          // Saddle: fixed split
          add(left, top);
          add(bottom, right);
          break;
        case 6:
          add(top, bottom);
          break;
        case 7:
          add(left, top);
          break;
        case 8:
          add(left, top);
          break;
        case 9:
          add(top, bottom);
          break;
        case 10:
          // Saddle: fixed split
          add(left, bottom);
          add(top, right);
          break;
        case 11:
          add(top, right);
          break;
        case 12:
          add(left, right);
          break;
        case 13:
          add(bottom, right);
          break;
        case 14:
          add(left, bottom);
          break;
        default:
          break;
      }
    }
  }

  const adjacency = new Map<string, Array<{ to: string; point: Point2; toPoint: Point2 }>>();
  const pointByKey = new Map<string, Point2>();

  for (const [a, b] of segments) {
    const ax = a.x + offsetU;
    const ay = a.y + offsetV;
    const bx = b.x + offsetU;
    const by = b.y + offsetV;
    pointByKey.set(a.key, [ax, ay]);
    pointByKey.set(b.key, [bx, by]);

    if (!adjacency.has(a.key)) {
      adjacency.set(a.key, []);
    }
    if (!adjacency.has(b.key)) {
      adjacency.set(b.key, []);
    }
    adjacency.get(a.key)!.push({ to: b.key, point: [ax, ay], toPoint: [bx, by] });
    adjacency.get(b.key)!.push({ to: a.key, point: [bx, by], toPoint: [ax, ay] });
  }

  const used = new Set<string>();
  const edgeId = (a: string, b: string) => (a < b ? `${a}|${b}` : `${b}|${a}`);
  const loops: Point2[][] = [];

  for (const startKey of adjacency.keys()) {
    const neighbors = adjacency.get(startKey) ?? [];
    for (const neighbor of neighbors) {
      const firstEdge = edgeId(startKey, neighbor.to);
      if (used.has(firstEdge)) {
        continue;
      }

      const loop: Point2[] = [];
      let prev = startKey;
      let curr = neighbor.to;
      loop.push(pointByKey.get(startKey)!);
      used.add(firstEdge);

      let guard = 0;
      while (curr !== startKey && guard < segments.length + 2) {
        loop.push(pointByKey.get(curr)!);
        const nextCandidates = adjacency.get(curr) ?? [];
        let nextKey: string | null = null;
        for (const candidate of nextCandidates) {
          if (candidate.to === prev) {
            continue;
          }
          const id = edgeId(curr, candidate.to);
          if (!used.has(id)) {
            nextKey = candidate.to;
            used.add(id);
            break;
          }
        }
        if (nextKey === null) {
          // Closed or dead-end: try remaining edge back to start
          for (const candidate of nextCandidates) {
            const id = edgeId(curr, candidate.to);
            if (candidate.to === startKey && !used.has(id)) {
              nextKey = candidate.to;
              used.add(id);
              break;
            }
          }
        }
        if (nextKey === null) {
          break;
        }
        prev = curr;
        curr = nextKey;
        guard += 1;
      }

      if (loop.length >= 3) {
        loops.push(loop);
      }
    }
  }

  return loops;
}

function smoothClosedLoop(loop: Point2[]): Point2[] {
  if (loop.length < 4) {
    return loop;
  }

  let points = loop.map(([x, y]) => [x, y] as Point2);

  for (let pass = 0; pass < SMOOTH_PASSES; pass++) {
    const next: Point2[] = [];
    const n = points.length;
    for (let i = 0; i < n; i++) {
      let sx = 0;
      let sy = 0;
      let count = 0;
      for (let d = -SMOOTH_WINDOW; d <= SMOOTH_WINDOW; d++) {
        const p = points[(i + d + n * 8) % n];
        sx += p[0];
        sy += p[1];
        count += 1;
      }
      next.push([sx / count, sy / count]);
    }
    points = next;
  }

  for (let iter = 0; iter < CHAIKIN_ITERATIONS; iter++) {
    points = chaikinClosed(points);
  }

  return points;
}

function chaikinClosed(points: Point2[]): Point2[] {
  const n = points.length;
  if (n < 3) {
    return points;
  }
  const next: Point2[] = [];
  for (let i = 0; i < n; i++) {
    const p0 = points[i];
    const p1 = points[(i + 1) % n];
    next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
    next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
  }
  return next;
}
